    for (int L = 0; L < 2; L++) {
        for (int o = 0; o < 80; o++) {
            long s = sock(fam[L], 2, 0);
            int res[8];
            for (int k = 0; k < 4; k++) {
                int x = vals[k];
                res[2 * k] = (int)setopt_(s, lv[L], o, &x, 4);
                int v = -7;
                unsigned l = 4;
                long g = getopt_(s, lv[L], o, &v, &l);
                res[2 * k + 1] = g < 0 ? -1000 : v;
            }
            close_(s);
            for (int k = 0; k < 8; k++) {
                if (res[k] != want_set[L][o][k]) {
                    snprintf(line, sizeof line, "hello487:   FAIL B level %d option %d: set %d -> %d get %d (Linux %d %d)\n", lv[L], o, vals[k / 2],
                             res[k & ~1], res[k | 1], want_set[L][o][k & ~1], want_set[L][o][k | 1]);
                    print(line);
                    failures++;
                    break;
                }
            }
        }
    }
    int b_fail = failures - a_fail;
    for (int L = 0; L < 2; L++) {
        long s = sock(fam[L], 1, 0);
        for (int o = 0; o < 80; o++) {
            char b[256] = { 0 };
            unsigned l = sizeof b;
            long r = getopt_(s, lv[L], o, b, &l);
            int got = r < 0 ? (int)r : (int)l;
            if (got != want_tcp[L][o]) {
                snprintf(line, sizeof line, "hello487:   FAIL C tcp level %d option %d: %d (Linux %d)\n", lv[L], o, got, want_tcp[L][o]);
                print(line);
                failures++;
            }
        }
        close_(s);
    }
    int c_fail = failures - a_fail - b_fail;
    for (int L = 0; L < 2; L++) {
        for (int o = 0; o < 80; o++) {
            long s = sock(fam[L], 1, 0);
            int res[8];
            for (int k = 0; k < 4; k++) {
                int x = vals[k];
                res[2 * k] = (int)setopt_(s, lv[L], o, &x, 4);
                int v = -7;
                unsigned l = 4;
                long g = getopt_(s, lv[L], o, &v, &l);
                res[2 * k + 1] = g < 0 ? -1000 : v;
            }
            close_(s);
            for (int k = 0; k < 8; k++) {
                if (res[k] != want_tcp_set[L][o][k]) {
                    snprintf(line, sizeof line, "hello487:   FAIL D tcp level %d option %d: set %d -> %d get %d (Linux %d %d)\n", lv[L], o, vals[k / 2],
                             res[k & ~1], res[k | 1], want_tcp_set[L][o][k & ~1], want_tcp_set[L][o][k | 1]);
                    print(line);
                    failures++;
                    break;
                }
            }
        }
    }
    int d_fail = failures - a_fail - b_fail - c_fail;
    for (int L = 0; L < 2; L++) {
        long s = sock(fam[L], 3, fam[L] == 10 ? 58 : 1);
        for (int o = 0; o < 80; o++) {
            char b[256] = { 0 };
            unsigned l = sizeof b;
            long r = getopt_(s, lv[L], o, b, &l);
            int got = r < 0 ? (int)r : (int)l;
            if (got != want_raw[L][o]) {
                snprintf(line, sizeof line, "hello487:   FAIL E raw level %d option %d: %d (Linux %d)\n", lv[L], o, got, want_raw[L][o]);
                print(line);
                failures++;
            }
        }
        close_(s);
    }
    int e_fail = failures - a_fail - b_fail - c_fail - d_fail;
